using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json.Linq;
public static class OperationalFix {public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var plan=JObject.Parse(File.ReadAllText(repo+"/SourceAssets/B5_OperationalDetail/layout.json"));var group=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("B5_Operational_Detail");int count=0;foreach(var q in plan["placements"]){var parent=group.Find((string)q["room"]);var t=parent.Find((string)q["id"]);if(!t){if((string)q["model"]!="OD_E03_WorkflowFloor")throw new Exception("Unexpected missing object");t=((GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Afrer_Seconds/05.Model/Environment/B5/OD_E03_WorkflowFloor.fbx"),parent)).transform;t.name=(string)q["id"];}var p=q["position"];t.localPosition=new Vector3((float)p[0],(float)p[1],(float)p[2]);t.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);foreach(var x in t.GetComponentsInChildren<Transform>()){PrefabUtility.RecordPrefabInstancePropertyModifications(x);PrefabUtility.RecordPrefabInstancePropertyModifications(x.gameObject);}count++;}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{placements=count};}}
